<script setup lang="ts">
import {computed,nextTick,onMounted,onUnmounted,ref,watch} from 'vue';
import {ArrowRight,BookOpen,Check,Copy,LoaderCircle,MessageSquare,Send,ShieldCheck,Sparkles,Square,Trash2} from 'lucide-vue-next';
import {marked} from 'marked';
import DOMPurify from 'dompurify';
import {searchGuideArticles,type GuideArticle} from '../lib/product-guide';
type Question={id:string;question:string;answer:string|null;status:string;model:string|null;error_message:string|null;guide_version:string;created_at:string};
const props=defineProps<{page:string|null;role:string;articles:GuideArticle[];draft:string;request:(path:string,method?:string,data?:unknown)=>Promise<any>}>();
const emit=defineEmits<{article:[id:string];navigate:[page:string];'update:draft':[value:string]}>();
const questions=ref<Question[]>([]);const loading=ref(true);const connected=ref(false);const sending=ref(false);const managing=ref(false);const error=ref('');const clearOpen=ref(false);const copied=ref('');const feed=ref<HTMLElement|null>(null);const input=ref<HTMLTextAreaElement|null>(null);
let disposed=false;let polling=false;let generation=0;let timer:ReturnType<typeof setTimeout>|undefined;let copyTimer:ReturnType<typeof setTimeout>|undefined;let attempt:{question:string;page:string;id:string}|null=null;
const pending=computed(()=>questions.value.find(item=>['queued','running'].includes(item.status)));
const latest=computed(()=>questions.value.at(-1));
const related=computed(()=>searchGuideArticles(props.articles,latest.value?.question??'',props.page).slice(0,3));
const suggestions=computed(()=>searchGuideArticles(props.articles,'',props.page).slice(0,3));
function markdown(text:string){return DOMPurify.sanitize(marked.parse(text,{async:false}) as string,{ALLOWED_TAGS:['p','strong','em','ul','ol','li','br','code','h2','h3','blockquote'],ALLOWED_ATTR:[]});}
function nearEnd(){const element=feed.value;return !element||element.scrollHeight-element.scrollTop-element.clientHeight<100;}
async function scroll(force=false,follow=true){await nextTick();if(force||follow)feed.value?.scrollTo({top:feed.value.scrollHeight,behavior:'auto'});}
function schedule(){if(timer)clearTimeout(timer);if(!disposed&&pending.value)timer=setTimeout(()=>{void load(false);},2000);}
async function load(initial=false,clearError=true){if(disposed||polling)return;polling=true;const expected=generation;const follow=nearEnd();try{const result=await props.request('/help/questions');if(disposed||expected!==generation)return;questions.value=result.questions;connected.value=result.connected;if(clearError)error.value='';loading.value=false;await scroll(initial,follow);}catch(e){if(!disposed&&expected===generation)error.value=(e as Error).message;}finally{polling=false;if(!disposed){loading.value=false;schedule();}}}
async function send(){const question=props.draft.trim(),page=props.page??'home';if(!question||question.length>4000||sending.value||pending.value||!connected.value)return;const follow=true;generation++;sending.value=true;error.value='';clearOpen.value=false;if(!attempt||attempt.question!==question||attempt.page!==page)attempt={question,page,id:crypto.randomUUID()};const requestId=attempt.id;try{const result=await props.request('/help/questions','POST',{question,page,request_id:requestId});if(disposed)return;const item=result.question as Question;questions.value=[...questions.value.filter(value=>value.id!==item.id),item];if(props.draft.trim()===question)emit('update:draft','');attempt=null;await scroll(true,follow);schedule();}catch(e){if(!disposed){error.value=(e as Error).message;void load(false,false);}}finally{if(!disposed)sending.value=false;}}
async function cancel(){const id=pending.value?.id;if(!id||managing.value)return;generation++;managing.value=true;error.value='';try{const result=await props.request(`/help/questions/${id}/cancel`,'POST');if(!disposed){questions.value=questions.value.map(item=>item.id===id?result.question:item);schedule();}}catch(e){if(!disposed)error.value=(e as Error).message;}finally{if(!disposed)managing.value=false;}}
async function clear(){if(managing.value||sending.value)return;generation++;managing.value=true;error.value='';try{await props.request('/help/questions','DELETE');if(!disposed){questions.value=[];clearOpen.value=false;attempt=null;schedule();}}catch(e){if(!disposed)error.value=(e as Error).message;}finally{if(!disposed)managing.value=false;}}
function ask(value:string){emit('update:draft',value);void nextTick(()=>input.value?.focus());}
async function copy(question:Question){try{await navigator.clipboard.writeText(question.answer??question.question);if(disposed)return;copied.value=question.id;if(copyTimer)clearTimeout(copyTimer);copyTimer=setTimeout(()=>copied.value='',1800);}catch{if(!disposed)error.value='Não foi possível copiar. Selecione o texto para copiá-lo.';}}
function keydown(event:KeyboardEvent){if(event.key==='Enter'&&(event.ctrlKey||event.metaKey)){event.preventDefault();void send();}}
watch(()=>props.page,()=>{attempt=null;});
onMounted(()=>{void load(true);});
onUnmounted(()=>{disposed=true;if(timer)clearTimeout(timer);if(copyTimer)clearTimeout(copyTimer);});
</script>
<template>
 <section class="product-help-chat" aria-label="Tira-dúvidas com IA"><header class="help-chat-heading"><div><Sparkles :size="17"/><span>Ajuda sobre o G-Analise IA</span></div><button v-if="questions.length" type="button" class="icon-button" aria-label="Limpar histórico da ajuda" :disabled="sending||managing" @click="clearOpen=!clearOpen"><Trash2 :size="15"/></button></header>
  <div v-if="clearOpen" class="help-chat-confirm" role="alert"><p>Apagar seu histórico de ajuda? As respostas em andamento serão interrompidas. Seus projetos e conversas de trabalho serão preservados.</p><div><button class="secondary-button" :disabled="managing" @click="clearOpen=false">Manter histórico</button><button class="secondary-button" :disabled="managing" @click="clear"><LoaderCircle v-if="managing" class="spin" :size="14"/><Trash2 v-else :size="14"/>Apagar histórico</button></div></div>
  <p class="sr-only" role="status" aria-live="polite">{{pending?'Resposta de ajuda em andamento.':latest?.status==='completed'?'Resposta de ajuda concluída.':latest?.status==='cancelled'?'Atendimento interrompido.':''}}</p>
  <p v-if="loading" class="help-chat-loading" role="status"><LoaderCircle class="spin" :size="18"/>Carregando seu atendimento…</p>
  <template v-else><div v-if="!connected" class="help-chat-offline"><BookOpen :size="20"/><div><strong>Os guias já estão disponíveis.</strong><p>Para conversar com a IA, conecte sua conta ChatGPT e autorize o uso do plano em Conexões.</p><button class="secondary-button" @click="emit('navigate','connections')">Ir para Conexões<ArrowRight :size="14"/></button></div></div>
   <div ref="feed" class="help-chat-feed" tabindex="0" aria-label="Histórico da ajuda"><div v-if="!questions.length" class="help-chat-intro"><span><MessageSquare :size="23"/></span><h3>O que você gostaria de entender?</h3><p>Pergunte sobre projetos, dashboards, conexões, prévias ou outras funcionalidades do sistema.</p><div><button v-for="article in suggestions" :key="article.id" :disabled="!connected" @click="ask(article.title)">{{article.title}}<ArrowRight :size="13"/></button></div></div>
    <article v-for="question in questions" :key="question.id" class="help-chat-exchange"><div class="help-chat-question"><small>Você</small><p>{{question.question}}</p></div><div class="help-chat-answer"><div class="help-answer-label"><Sparkles :size="13"/><small>Ajuda G-Analise IA</small><button v-if="question.answer" class="icon-button" :aria-label="copied===question.id?'Resposta copiada':'Copiar resposta'" @click="copy(question)"><Check v-if="copied===question.id" :size="13"/><Copy v-else :size="13"/></button></div><div v-if="question.answer" class="guide-markdown" v-html="markdown(question.answer)"></div><p v-if="question.status==='queued'||question.status==='running'" class="help-chat-status" role="status"><LoaderCircle class="spin" :size="13"/>{{question.status==='queued'?'Aguardando atendimento…':'Consultando as orientações do sistema…'}}</p><p v-else-if="question.status==='failed'" class="help-chat-failure">{{question.error_message??'Esta resposta não foi concluída. Envie uma nova pergunta para continuar.'}}</p><p v-else-if="question.status==='cancelled'" class="help-chat-status">Atendimento interrompido.{{question.answer?' O texto acima pode estar incompleto.':''}}</p><small v-if="question.status==='completed'" class="help-chat-source">Orientações da versão {{question.guide_version}}</small></div></article>
   </div>
   <div v-if="latest&&['completed','failed','cancelled'].includes(latest.status)" class="help-chat-related"><small>Continue pelas orientações</small><button v-if="related[0]" class="help-chat-mobile-guide" @click="emit('article',related[0].id)"><BookOpen :size="12"/>Ver guia relacionado</button><div><button v-for="article in related" :key="article.id" @click="emit('article',article.id)"><BookOpen :size="12"/>{{article.title}}</button></div><button v-if="role!=='viewer'" class="help-chat-work" @click="emit('navigate','home')">Abrir Criar com IA<ArrowRight :size="13"/></button></div>
   <form class="help-chat-composer" @submit.prevent="send"><label for="product-help-question">Sua dúvida sobre o sistema</label><textarea id="product-help-question" ref="input" :value="draft" maxlength="4000" rows="2" placeholder="Ex.: Para que servem os projetos aqui dentro?" :disabled="!connected||sending" @input="emit('update:draft',($event.target as HTMLTextAreaElement).value)" @keydown="keydown"></textarea><div><small><span>{{draft.length}}/4000</span><span> · Ctrl/⌘ + Enter para enviar</span></small><button v-if="pending" type="button" class="secondary-button" :disabled="managing" @click="cancel"><LoaderCircle v-if="managing" class="spin" :size="14"/><Square v-else :size="12"/>Interromper</button><button v-else type="submit" class="primary-button" :disabled="!connected||!draft.trim()||draft.trim().length>4000||sending||managing"><LoaderCircle v-if="sending" class="spin" :size="14"/><Send v-else :size="14"/>Enviar</button></div></form>
   <details class="help-chat-privacy"><summary><ShieldCheck :size="13"/>Usa seu plano ChatGPT · sobre este atendimento</summary><p>A pergunta e as orientações do produto são enviadas à OpenAI usando sua autorização e os limites do seu plano. Este atendimento orienta; as operações no BI acontecem em Criar com IA. Evite enviar senhas ou dados sensíveis.</p></details>
  </template><div v-if="error" class="help-chat-failure" role="alert"><p>{{error}}</p><button v-if="!loading" class="secondary-button" :disabled="polling" @click="load(false)">Atualizar atendimento</button></div>
 </section>
</template>
<style scoped>
