tify-self:end;max-width:90%;background:#eef4ff;border:1px solid #e1eaff;border-radius:13px 13px 3px 13px;padding:12px 15px;color:#526f97}.help-chat-question small{font-size:9px;color:#8ca3c1}.help-chat-question p{font-size:13px;line-height:1.8;white-space:pre-wrap;overflow-wrap:anywhere;margin:5px 0 0}.help-chat-answer{padding:0 5px}.help-answer-label{display:flex;align-items:center;gap:7px;color:#7596c0;margin-bottom:9px}.help-answer-label small{font-size:10px}.help-answer-label button{margin-left:auto}.help-chat-status{display:flex;align-items:center;gap:7px;font-size:11px;color:#8da0b8;margin:10px 0;line-height:1.7}.help-chat-failure{color:#a37d41;font-size:12px;line-height:1.8;background:#fff9ef;border:1px solid #f1e7d5;border-radius:8px;padding:12px;margin:12px 0}.help-chat-failure p{margin:0 0 10px}.help-chat-failure button{font-size:11px}.help-chat-source{display:block;font-size:9px;color:#a2b0c4;margin-top:9px}.help-chat-related{display:flex;align-items:center;gap:12px;border-top:1px solid #e6edf6;padding:8px 0 3px;min-width:0}.help-chat-related>small{display:none}.help-chat-related>div{display:flex;gap:7px;flex:1;min-width:0;overflow:auto;margin:0}.help-chat-related>div button{display:flex;align-items:center;gap:6px;border:1px solid #e2eaf5;background:#fff;color:#7a94b7;padding:7px 9px;font-size:10px;border-radius:7px;line-height:1.5;text-align:left;white-space:nowrap;flex-shrink:0}.help-chat-work{display:flex;align-items:center;gap:7px;flex-shrink:0;border:0;background:transparent;color:#0861ee;font-size:11px;padding:6px 0}.help-chat-composer{margin-top:10px;border:1px solid #dce6f4;border-radius:10px;padding:10px;background:#fff}.help-chat-composer:focus-within{outline:2px solid #0861ee;outline-offset:2px}.help-chat-composer label{font-size:10px;font-weight:600;color:#6f88aa}.help-chat-composer textarea{display:block;width:100%;box-sizing:border-box;resize:vertical;height:54px;min-height:48px;max-height:112px;border:0;background:transparent;outline:0;font:inherit;font-size:13px;line-height:1.65;color:#526e93;padding:5px 0}.help-chat-composer textarea::placeholder{color:#a0aec2}.help-chat-composer>div{display:flex;align-items:center;justify-content:space-between;gap:10px}.help-chat-composer>div>small{font-size:9px;color:#a1afc2}.help-chat-composer button{font-size:11px;min-height:35px;padding:8px 12px}.help-chat-privacy{font-size:9px;line-height:1.8;color:#98a8bf;margin:7px 0 0}.help-chat-privacy summary{display:flex;align-items:center;gap:7px;cursor:pointer;color:#879db9;font-size:10px}.help-chat-privacy summary:focus-visible{outline:2px solid #0861ee;outline-offset:3px}.help-chat-privacy p{margin:8px 0 0}.help-chat-privacy svg{flex-shrink:0}.help-chat-mobile-guide{display:none}.help-chat-intro button:disabled{opacity:.55;cursor:default}
.help-chat-heading,.help-chat-confirm,.help-chat-offline,.help-chat-related,.help-chat-composer,.help-chat-privacy,.help-chat-failure{flex-shrink:0}.help-chat-related>div{max-height:40px;overscroll-behavior:contain}
@media(max-width:600px){.help-chat-feed{max-height:none;min-height:80px}.help-chat-question{max-width:94%}.help-chat-composer>div>small{font-size:8px;max-width:135px}.help-chat-intro>div{display:grid}.help-chat-heading>div{font-size:12px}.help-chat-composer textarea{font-size:16px;line-height:1.5}}
@media(max-width:600px){.help-chat-related{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:8px 0 3px}.help-chat-related>small,.help-chat-related>div{display:none}.help-chat-mobile-guide{display:flex;align-items:center;gap:5px;border:0;background:transparent;color:#7a94b7;font-size:10px;padding:5px 0;text-align:left}.help-chat-composer textarea{height:60px;min-height:48px}.help-chat-composer{padding:10px}.help-chat-feed{min-height:100px}.help-chat-privacy{margin-top:7px}}
@media(max-height:700px){.help-chat-related{display:none}.help-chat-privacy{font-size:8px;line-height:1.5}.help-chat-heading{margin-bottom:5px}.help-chat-composer textarea{min-height:44px;height:54px}.help-chat-composer{margin-top:8px;padding:9px}.help-chat-feed{min-height:70px}}
@media(max-width:600px) and (max-height:700px){.help-chat-composer textarea{height:56px;line-height:1.4}}
