 .help-chat-composer>div{grid-column:2;grid-row:2;flex-direction:column;justify-content:center;align-items:flex-end;gap:2px}
 .help-chat-composer>div>small{font-size:8px;line-height:1.4}
 .help-chat-composer>div>small>span+span{display:none}
}
